// Parse and validate classification request
const input = $input.first().json;
const body = input.body || input;

if (!body.content && !body.text) {
  throw new Error('Missing required field: content or text');
}

const request = {
  id: `cls_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
  content: body.content || body.text,
  metadata: body.metadata || {},
  categories: body.categories || null, // Custom categories if provided
  confidenceThreshold: body.confidenceThreshold || 0.85,
  createdAt: new Date().toISOString()
};

return [{ json: request }];

