// Parse AI response and evaluate confidence
const request = $('Parse Request').first().json;
const aiResponse = $input.first().json;

let classification;
try {
  const content = aiResponse.message?.content || aiResponse.choices?.[0]?.message?.content || '{}';
  classification = JSON.parse(content);
} catch (e) {
  classification = {
    primary_category: 'other',
    confidence: 0,
    error: 'Failed to parse AI response'
  };
}

const result = {
  ...request,
  classification,
  meetsThreshold: classification.confidence >= request.confidenceThreshold,
  requiresReview: classification.confidence < request.confidenceThreshold,
  processedAt: new Date().toISOString()
};

return [{ json: result }];

// Auto-route based on category
const result = $input.first().json;
const category = result.classification.primary_category;

// Routing rules (in production, load from database)
const routingRules = {
  support: { queue: 'support-team', priority: result.classification.urgency === 'high' ? 1 : 3 },
  sales: { queue: 'sales-team', priority: 2 },
  billing: { queue: 'billing-team', priority: result.classification.urgency === 'high' ? 1 : 2 },
  feedback: { queue: 'product-team', priority: 4 },
  bug_report: { queue: 'engineering-team', priority: result.classification.urgency === 'high' ? 1 : 2 },
  feature_request: { queue: 'product-team', priority: 5 },
  spam: { queue: 'spam-filter', priority: 10, autoArchive: true },
  other: { queue: 'general-inbox', priority: 5 }
};

const routing = routingRules[category] || routingRules['other'];

return [{
  json: {
    ...result,
    routing,
    autoRouted: true,
    routedAt: new Date().toISOString()
  }
}];

// Add to human review queue
const result = $input.first().json;
const staticData = $workflow.staticData;

// Initialize review queue
if (!staticData.reviewQueue) {
  staticData.reviewQueue = [];
}

const reviewItem = {
  id: result.id,
  content: result.content.substring(0, 200) + (result.content.length > 200 ? '...' : ''),
  suggestedCategory: result.classification.primary_category,
  confidence: result.classification.confidence,
  secondaryCategory: result.classification.secondary_category,
  sentiment: result.classification.sentiment,
  urgency: result.classification.urgency,
  addedAt: new Date().toISOString(),
  status: 'pending_review'
};

staticData.reviewQueue.push(reviewItem);

// Keep queue manageable
if (staticData.reviewQueue.length > 100) {
  staticData.reviewQueue = staticData.reviewQueue.slice(-100);
}

return [{
  json: {
    ...result,
    inReviewQueue: true,
    queuePosition: staticData.reviewQueue.length,
    reviewUrl: `http://localhost:5678/webhook/classify/review?id=${result.id}`
  }
}];

// Collect training data for model improvement
const result = $input.first().json;
const staticData = $workflow.staticData;

// Initialize training data collection
if (!staticData.trainingData) {
  staticData.trainingData = [];
}

const trainingExample = {
  id: result.id,
  content: result.content,
  aiPrediction: result.classification.primary_category,
  aiConfidence: result.classification.confidence,
  humanLabel: null, // To be filled after review
  feedback: null,
  collectedAt: new Date().toISOString()
};

staticData.trainingData.push(trainingExample);

// Keep last 1000 examples
if (staticData.trainingData.length > 1000) {
  staticData.trainingData = staticData.trainingData.slice(-1000);
}

return [{ json: { ...result, trainingDataCollected: true } }];

// Calculate and log accuracy metrics
const result = $input.first().json;
const staticData = $workflow.staticData;

// Initialize metrics
if (!staticData.metrics) {
  staticData.metrics = {
    total: 0,
    autoRouted: 0,
    manualReview: 0,
    categoryBreakdown: {},
    avgConfidence: 0,
    confidenceSum: 0
  };
}

const m = staticData.metrics;
m.total++;
if (result.autoRouted) m.autoRouted++;
if (result.inReviewQueue) m.manualReview++;

const category = result.classification.primary_category;
m.categoryBreakdown[category] = (m.categoryBreakdown[category] || 0) + 1;

m.confidenceSum += result.classification.confidence;
m.avgConfidence = m.confidenceSum / m.total;

const metrics = {
  total: m.total,
  autoRoutedRate: ((m.autoRouted / m.total) * 100).toFixed(2) + '%',
  manualReviewRate: ((m.manualReview / m.total) * 100).toFixed(2) + '%',
  avgConfidence: (m.avgConfidence * 100).toFixed(2) + '%',
  topCategories: Object.entries(m.categoryBreakdown)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 5)
    .map(([cat, count]) => ({ category: cat, count }))
};

return [{
  json: {
    ...result,
    metrics
  }
}];

// Format final response
const result = $input.first().json;

return [{
  json: {
    success: true,
    classificationId: result.id,
    classification: {
      category: result.classification.primary_category,
      confidence: result.classification.confidence,
      secondaryCategory: result.classification.secondary_category,
      sentiment: result.classification.sentiment,
      urgency: result.classification.urgency,
      keywords: result.classification.keywords,
      summary: result.classification.summary
    },
    routing: result.autoRouted ? result.routing : null,
    requiresReview: result.requiresReview,
    reviewQueue: result.inReviewQueue ? {
      position: result.queuePosition,
      reviewUrl: result.reviewUrl
    } : null,
    processedAt: result.processedAt
  }
}];
